FICHES.append(fiche(
 id='von-der-leyen-pas-elue', affirmation="Ursula von der Leyen n'a jamais été élue : personne n'a voté pour elle.", volet='politique', sous_theme='Union européenne',
 mots_cles=['von der leyen pas elue', 'von der leyen non elue', 'personne n a vote pour von der leyen', 'qui a elu von der leyen', 'presidente commission europeenne elue', 'commission europeenne non elue', 'eurocrates non elus', 'election president commission europeenne', 'spitzenkandidat', 'vote parlement europeen von der leyen'],
 verdict='trompeur', fiabilite='etabli',
 resume="Trompeur. Ursula von der Leyen n'a pas été élue au suffrage universel direct, mais elle a bien été élue : par le Parlement européen, lui-même élu par les citoyens, à la majorité absolue de ses membres, avec 383 voix en 2019 (seuil de 374) et 401 voix en 2024 (seuil de 361), sur proposition des chefs d'État et de gouvernement. Sa Commission a été approuvée par le Parlement en novembre 2024 et peut être renversée par une motion de censure. C'est le même principe que pour un Premier ministre en régime parlementaire. La critique d'un déficit démocratique, elle, reste légitime : en 2019, elle n'était candidate à rien lors des élections européennes.",
 contexte="L'argument d'une présidente « non élue » sert à présenter l'Union européenne comme une technocratie illégitime. Il mélange deux choses : l'élection au suffrage direct, qui n'existe pas pour ce poste, et l'élection par une assemblée élue, prévue par le traité.",
 explication="On lit l'article 17 du traité sur l'Union européenne, puis on vérifie les votes du Parlement européen de 2019, 2024 et 2025 dans les sources institutionnelles, avant de discuter les limites démocratiques réelles de la procédure.",
 sources=[B_VDL_TUE, B_VDL_SEAE, B_VDL_PS, B_VDL_PE24, B_VDL_PE25, B_VDL_EN],
 faits=[
  fait("Selon l'article 17, paragraphe 7, du traité sur l'Union européenne, le Conseil européen propose un candidat à la présidence de la Commission en tenant compte des élections au Parlement européen, et le Parlement européen l'élit à la majorité des membres qui le composent.", 'b_vdl_tue', 'depuis 2009', 'Union européenne', "Le traité parle bien d'une élection, par l'assemblée élue au suffrage universel direct.", 'etabli'),
  fait("Selon le Service européen pour l'action extérieure, le Parlement européen a élu Ursula von der Leyen le 16 juillet 2019 par 383 voix pour, 327 contre et 22 abstentions, le seuil requis étant de 374 voix.", 'b_vdl_seae', '2019', 'Union européenne', "Elle a été élue de justesse, avec neuf voix de plus que la majorité absolue.", 'etabli', '383'),
  fait("Selon Public Sénat, le Parlement européen l'a réélue le 18 juillet 2024 avec 401 voix, alors que 361 étaient nécessaires.", 'b_vdl_ps', '2024', 'Union européenne', "Le Parlement issu des élections de juin 2024 l'a reconduite avec une marge plus large.", 'etabli', '401'),
  fait("Selon le Parlement européen, le collège des commissaires a été approuvé le 27 novembre 2024 par 370 voix pour, 282 contre et 36 abstentions, après les auditions de chaque commissaire désigné.", 'b_vdl_pe24', '2024', 'Union européenne', "Toute l'équipe passe aussi devant les élus, comme un gouvernement qui sollicite la confiance.", 'etabli', '370'),
  fait("Selon le Parlement européen, une motion de censure contre la Commission a été rejetée le 10 juillet 2025 par 175 voix pour, 360 contre et 18 abstentions ; son adoption exigeait les deux tiers des suffrages exprimés représentant la majorité des membres.", 'b_vdl_pe25', '2025', 'Union européenne', "La Commission est responsable devant le Parlement, qui peut la renverser, même si le seuil est très élevé.", 'etabli', '175'),
  fait("Fait défavorable : selon Euronews, en 2019 les dirigeants européens ont écarté toutes les têtes de liste des partis européens et choisi Ursula von der Leyen, qui n'avait pas participé à la campagne ; en 2024, elle était tête de liste du Parti populaire européen mais ne figurait sur aucun bulletin de vote.", 'b_vdl_en', '2019-2024', 'Union européenne', "Les électeurs n'ont pas pu choisir directement entre des candidats à la présidence de la Commission : la critique d'un déficit démocratique a une base réelle.", 'etabli'),
 ],
 court="Elle n'a pas été élue au suffrage direct, mais elle a été élue par le Parlement européen, lui-même élu par les citoyens : 383 voix en 2019, 401 en 2024, chaque fois à la majorité absolue des députés. C'est le principe d'un Premier ministre en régime parlementaire. On peut critiquer la procédure, mais pas dire que personne n'a voté.",
 moyen="Le traité sur l'Union européenne prévoit que les chefs d'État et de gouvernement proposent un candidat en tenant compte des élections européennes, puis que le Parlement européen l'élit à la majorité de ses membres. Ursula von der Leyen a ainsi été élue le 16 juillet 2019 avec 383 voix (il en fallait 374), puis réélue le 18 juillet 2024 avec 401 voix (il en fallait 361). Son équipe a été approuvée par les députés le 27 novembre 2024, et une motion de censure a été rejetée en juillet 2025.\n\nC'est le fonctionnement d'un régime parlementaire : en Allemagne ou en Italie, le chef du gouvernement n'est pas élu au suffrage direct non plus. La vraie critique est ailleurs : en 2019, elle n'était même pas candidate lors de la campagne européenne, choisie en coulisses par les dirigeants nationaux. Le déficit démocratique existe, mais il ne se résume pas à « personne n'a voté pour elle ».",
 detaille="L'affirmation confond deux choses : être élu au suffrage universel direct, et être élu par une assemblée élue. Le président de la Commission européenne n'a jamais été élu directement par les citoyens, et le traité ne le prévoit pas. Mais il est élu, au sens strict, par le Parlement européen.\n\nL'article 17 du traité sur l'Union européenne organise la procédure. Le Conseil européen, qui réunit les chefs d'État et de gouvernement élus de chaque pays, propose un candidat en tenant compte des élections au Parlement européen. Le Parlement l'élit ensuite à la majorité absolue de ses membres. Le 16 juillet 2019, Ursula von der Leyen a obtenu 383 voix, pour un seuil de 374. Le 18 juillet 2024, le nouveau Parlement l'a réélue avec 401 voix, pour un seuil de 361.\n\nLe contrôle ne s'arrête pas là. Chaque commissaire est auditionné, puis le collège entier est soumis au vote : le 27 novembre 2024, il a été approuvé par 370 voix contre 282. La Commission est responsable devant le Parlement, qui peut la renverser par une motion de censure : celle de juillet 2025, déposée à l'initiative de l'extrême droite, a recueilli 175 voix seulement.\n\nC'est la logique de tout régime parlementaire : en Allemagne, en Italie ou en Espagne, le chef du gouvernement est choisi par les députés, et personne ne le dit « non élu ». En France, d'ailleurs, le Premier ministre n'est élu par personne.\n\nIl serait malhonnête de s'arrêter là. En 2019, les dirigeants européens ont écarté les têtes de liste présentées aux électeurs et choisi une ministre allemande qui n'avait fait aucune campagne, élue avec neuf voix d'avance. Le seuil de la censure est si élevé qu'il protège la Commission. Pour la gauche, la réponse n'est pas de nier tout vote, mais d'exiger plus de démocratie : un Parlement doté de l'initiative des lois, une Commission plus responsable et des choix économiques débattus devant les citoyens.",
 empathie="Beaucoup de gens ont le sentiment que les décisions européennes leur échappent, et ce sentiment repose sur des faits réels. On peut le prendre au sérieux sans répéter une formule fausse.",
 legitimes=["En 2019, Ursula von der Leyen n'était pas candidate lors des élections européennes : les électeurs ne l'ont pas choisie directement.", "Le choix du candidat se fait d'abord entre chefs d'État et de gouvernement, souvent dans des négociations opaques.", "La Commission dispose de pouvoirs importants, notamment l'initiative des lois, et la censure exige une majorité très difficile à atteindre."],
 contre=[
  ("Elle a été nommée, pas élue.", "Le traité dit que le Parlement européen « élit » le candidat proposé : 383 voix en 2019, 401 en 2024, à la majorité absolue des députés."),
  ("Le Parlement européen ne compte pas, ce sont des eurocrates.", "Les députés européens sont élus au suffrage universel direct par les citoyens de chaque pays, dont les Français, et ils peuvent renverser la Commission."),
  ("Macron, lui, a été élu par le peuple.", "Oui, mais en France le Premier ministre n'est élu par personne, et dans la plupart des démocraties européennes le chef du gouvernement est choisi par le Parlement : c'est le même principe."),
 ],
 questions=["Dirais-tu que le chancelier allemand ou le Premier ministre italien ne sont pas élus ?", "Qu'est-ce qui rendrait selon toi la Commission européenne plus démocratique ?"],
 limites=["L'article 17 du traité a été lu en anglais, à travers un outil de lecture qui paraphrase ; un article de Public Sénat de 2018, lu mais non retenu, cite la formule française « tenir compte des élections au Parlement européen ».", "Les voix contre et abstentions de 2024 ne sont pas données par les sources lues pour l'élection de la présidente.", "La comparaison avec les régimes parlementaires est une interprétation : le Conseil européen joue un rôle de proposition qui n'a pas d'équivalent exact au niveau national."],
 publics={'convaincus': "Tu as raison sur un point : on ne vote pas directement pour la présidente de la Commission. Mais les députés européens que tu élis l'ont élue deux fois, à la majorité absolue, et ils peuvent la renverser. Si tu dis qu'elle n'est pas élue, il faut dire la même chose de tous les Premiers ministres d'Europe. La vraie bataille, c'est d'exiger plus de démocratie, pas de faire croire que personne ne vote.",
  'indecis': "Ton impression que l'Europe décide loin de toi est compréhensible. Les faits : Ursula von der Leyen a été élue par le Parlement européen, avec 383 voix en 2019 et 401 en 2024, et son équipe a dû obtenir la confiance des députés. Mais en 2019, elle n'était pas candidate pendant la campagne : c'est cela qu'on peut légitimement critiquer."},
 a_actualiser='2029-07-31', raison="Prochaine élection du président de la Commission après les élections européennes de 2029, ou nouvelle motion de censure.",
))

