 mots_cles=['immunite parlementaire', 'les deputes sont intouchables', 'immunite des elus delinquants', 'levee de l immunite', 'inviolabilite parlementaire', 'irresponsabilite parlementaire', 'article 26 constitution', 'un depute peut il etre poursuivi', 'elus au dessus des lois', 'bureau de l assemblee immunite', 'depute mis en examen'],
