FICHES.append(fiche(
 id='retraite-deputes-un-mandat', affirmation="Après un seul mandat, les députés touchent une grosse retraite à vie.", volet='politique', sous_theme='Institutions françaises',
 mots_cles=['retraite des deputes', 'retraite a vie apres un mandat', 'pension depute un mandat', 'retraite des parlementaires', 'les deputes ont une retraite en or', 'regime special deputes', 'retraite senateurs', 'combien touche un depute a la retraite', 'cinq ans depute retraite', 'privileges des elus retraite'],
 verdict='trompeur', fiabilite='estimation',
 resume="Trompeur pour les députés. Un mandat ouvre des droits à pension, comme tout emploi, mais pas une retraite immédiate ni une rente confortable : la pension est calculée au prorata des années cotisées et ne peut être touchée qu'à l'âge légal (64 ans à terme). Pour un mandat de cinq ans, elle était d'environ 664 € nets par mois selon l'Assemblée nationale citée par Public Sénat en 2019. Le régime spécial a été supprimé en 2018 ; il reste en revanche plus généreux au Sénat, où un seul mandat rapportait environ 2 190 € nets en 2019.",
 contexte="L'idée d'une « retraite en or » des élus circule depuis longtemps, souvent nourrie par l'ancien régime des députés, qui était beaucoup plus avantageux. Elle sert à présenter tous les élus comme une caste privilégiée.",
 explication="On compare les règles actuelles décrites par l'Assemblée nationale avec les montants publiés pour un mandat, avant et après la réforme de 2018, et avec le régime du Sénat.",
 sources=[E_RET_FICHE7, E_RET_PS2019, E_RET_PS2017, E_RET_LCP, E_RET_REC],
 faits=[
  fait("Selon l'Assemblée nationale, une réforme décidée le 8 novembre 2017 et entrée en vigueur le 1er janvier 2018 a supprimé le régime complémentaire, réduit la base de calcul de la pension et aligné les bonifications familiales sur la fonction publique.", 'e_ret_fiche7', 'depuis 2018', 'Assemblée nationale', "Le régime des députés a été nettement rapproché du droit commun.", 'etabli', '2018'),
  fait("Selon l'Assemblée nationale, la pension est calculée au prorata des annuités acquises (dans la limite de 42,25 annuités à compter de septembre 2023) et ne peut être liquidée qu'à partir de 62 ans et 3 mois, âge qui monte progressivement à 64 ans selon les règles de droit commun.", 'e_ret_fiche7', '2023-2026', 'Assemblée nationale', "Un ancien député de quarante ans ne touche rien avant l'âge légal, comme tout le monde.", 'etabli', '64 ans'),
  fait("Selon Public Sénat (2019), citant le site de l'Assemblée nationale, les droits à retraite ouverts par un mandat de député sont passés de 1 053 € à 664 € nets par mois avec la réforme.", 'e_ret_ps2019', '2019', 'Assemblée nationale', "Cinq ans de mandat donnent une pension partielle modeste, proportionnelle à la durée.", 'estimation', '664 €'),
  fait("Selon le site La Retraite en clair, en 2023, la pension pour cinq ans de mandat était de 684,38 € nets par mois.", 'e_ret_rec', '2023', 'Assemblée nationale', "Un ordre de grandeur cohérent avec le chiffre de 2019, à manier avec prudence car la source est privée.", 'estimation', '684 €'),
  fait("Selon LCP, le Bureau de l'Assemblée a gelé à l'unanimité les pensions des anciens députés pour 2026, pour une économie de 800 000 euros, alors qu'elles sont habituellement revalorisées de plein droit.", 'e_ret_lcp', '2026', 'Assemblée nationale', "L'Assemblée décide elle-même de son régime, ce qui alimente la défiance, mais elle l'a resserré.", 'etabli', '800 000 €'),
  fait("Fait défavorable : selon Public Sénat (2019), la pension moyenne des anciens députés était de 2 675 € nets par mois et, au Sénat, un seul mandat de sénateur rapportait 2 190 € nets par mois ; selon l'Assemblée nationale, la caisse des députés est en partie financée par une subvention du budget de l'Assemblée.", 'e_ret_ps2019', '2018-2019', 'France', "Le régime sénatorial reste avantageux et les pensions moyennes, qui reflètent l'ancien régime et de longues carrières, sont élevées.", 'estimation', '2 190 €'),
 ],
 court="Pas vraiment. Depuis 2018, la pension d'un député est calculée au prorata des années cotisées et n'est versée qu'à l'âge légal. Pour un mandat de cinq ans, elle était d'environ 664 € nets par mois en 2019 selon l'Assemblée nationale. Le régime du Sénat reste en revanche plus généreux.",
 moyen="Comme tout travailleur, un député cotise et acquiert des droits à pension. Mais depuis la réforme entrée en vigueur le 1er janvier 2018, le régime spécial de l'Assemblée a été supprimé : la pension est calculée au prorata des annuités, et elle n'est versée qu'à partir de l'âge légal, qui passe progressivement de 62 ans et 3 mois à 64 ans. Pour un seul mandat de cinq ans, les droits sont passés de 1 053 € à 664 € nets par mois, selon les chiffres de l'Assemblée cités par Public Sénat en 2019.\n\nIl y a une part de vrai : la pension moyenne des anciens députés reste élevée (2 675 € nets en 2019), car elle reflète l'ancien régime et de longues carrières, et le Sénat garde un régime avantageux, avec environ 2 190 € nets pour un seul mandat. La bonne revendication, c'est d'aligner tous les élus sur le droit commun, pas de faire croire que cinq ans à l'Assemblée garantissent une rente.",
 detaille="L'affirmation mélange plusieurs choses : l'ancien régime des députés, le régime actuel et celui des sénateurs.\n\nJusqu'en 2017, les députés bénéficiaient d'un régime spécial très favorable. Le Bureau de l'Assemblée a décidé le 8 novembre 2017 d'y mettre fin, avec effet au 1er janvier 2018 : suppression du régime complémentaire, réduction de la base de calcul, alignement des bonifications familiales sur la fonction publique. Public Sénat parlait alors de « la fin du régime spécial », pour une économie d'environ dix millions d'euros par an à terme.\n\nAujourd'hui, selon l'Assemblée nationale, la pension est calculée au prorata des annuités, dans la limite de 42,25 annuités, et ne peut être perçue qu'à partir de l'âge légal, qui monte vers 64 ans comme pour tout le monde. Un député cotise 10,85 % de son indemnité. Pour un mandat de cinq ans, les droits sont d'environ 664 € nets par mois selon les chiffres de l'Assemblée cités en 2019 (684 € en 2023 selon un site spécialisé). C'est une pension « à vie », comme toute pension, mais modeste et différée.\n\nLe soupçon de privilège n'est pas pour autant sans fondement. La pension moyenne des anciens députés atteignait 2 675 € nets en 2019, car beaucoup ont cotisé sous l'ancien régime ou pendant plusieurs mandats ; la caisse reçoit une subvention du budget de l'Assemblée ; et au Sénat, un seul mandat de six ans rapportait environ 2 190 € nets par mois en 2019. En décembre 2025, le Bureau de l'Assemblée a gelé les pensions des anciens députés pour 2026.\n\nPour la gauche, l'enjeu n'est pas de nourrir le rejet des élus, mais d'exiger l'égalité : les représentants du peuple devraient relever des mêmes règles que les travailleurs qu'ils représentent, au Sénat comme à l'Assemblée. Et l'on peut retourner la question : ceux qui dénoncent ces pensions défendent-ils aussi une retraite digne pour tous ?",
 empathie="Quand on a travaillé toute sa vie pour une petite pension, l'idée que des élus soient mieux traités est révoltante, et c'est légitime de demander des comptes. Mais il faut viser juste : le régime des députés a été réformé, celui du Sénat beaucoup moins.",
 legitimes=["Les élus fixent eux-mêmes leur régime de retraite, ce qui pose un problème démocratique.", "Le régime des sénateurs reste nettement plus favorable que celui des députés.", "La pension moyenne des anciens parlementaires est élevée par rapport à celle des Français."],
 contre=[
  ("Un député touche sa retraite dès la fin de son mandat.", "Non : selon l'Assemblée nationale, la pension n'est versée qu'à l'âge légal (vers 64 ans), comme pour les autres assurés."),
  ("Cinq ans suffisent pour toucher une grosse pension.", "Pour un mandat de cinq ans, les droits sont d'environ 664 € nets par mois selon les chiffres de l'Assemblée cités par Public Sénat. C'est au Sénat que le régime reste généreux."),
  ("Rien n'a changé, c'est toujours un régime spécial.", "Le régime spécial des députés a été supprimé au 1er janvier 2018 et les pensions des anciens députés ont été gelées pour 2026."),
 ],
 questions=["Savais-tu que la pension d'un député dépend du nombre d'années cotisées et n'est versée qu'à l'âge légal ?", "Plutôt que de viser les seuls élus, ne faudrait-il pas exiger une retraite digne pour tout le monde ?"],
 limites=["Les montants pour un mandat (664 € en 2019) et la pension moyenne (2 675 €) viennent de Public Sénat citant le site de l'Assemblée nationale, page qui n'a pas été ouverte ; ces données datent de 2018-2019.", "Le montant de 684,38 € en 2023 vient d'un site d'information privé, à manier avec prudence.", "La fiche officielle de l'Assemblée (janvier 2026) ne donne ni pension moyenne ni montant pour un mandat ; elle a été lue à travers un outil de lecture qui résume.", "Les montants du régime du Sénat datent de 2019 et ont pu changer depuis.", "Le poids de la subvention de l'Assemblée dans le financement de la caisse n'a pas été chiffré."],
 publics={'convaincus': "Je partage ton exigence que les élus ne soient pas des privilégiés. Mais depuis 2018, un député qui fait un seul mandat touche environ 600 à 700 € par mois, et seulement à l'âge légal, comme toi. Si tu veux un combat juste, c'est le régime des sénateurs qu'il faut viser, et l'égalité de tous devant la retraite.",
  'indecis': "C'est normal de se poser la question, les élus votent leurs propres règles. Les faits : la pension d'un député est proportionnelle aux années cotisées, environ 664 € nets pour cinq ans selon l'Assemblée, et versée à l'âge légal. Le Sénat reste plus généreux : c'est là que la critique porte vraiment."},
 a_actualiser='2027-06-30', raison="Montants actualisés des pensions des parlementaires et éventuelle réforme du régime du Sénat.",
))

