FICHES.append(fiche(
 id='treve-hivernale-impayes', affirmation="Avec la trêve hivernale, les locataires peuvent arrêter de payer leur loyer pendant des mois sans risque.", volet='economie', sous_theme='Loyers',
 mots_cles=['treve hivernale loyer', 'treve hivernale ne pas payer', 'locataires mauvais payeurs', 'impayes de loyer', 'expulsion locataire hiver', 'loi kasbarian berge', 'proprietaire loyers impayes', 'squatteurs treve hivernale', 'on peut plus expulser', 'expulsions locatives record', 'garantie visale'],
 verdict='contredit', fiabilite='etabli',
 resume="Faux. La trêve hivernale, du 1er novembre au 31 mars, suspend seulement l'exécution des expulsions et les coupures d'énergie ; elle ne supprime ni le loyer ni la dette, qui continuent de courir, et les procédures avancent. Les expulsions avec la force publique ont atteint des records : 19 023 en 2023, 24 556 en 2024. Les ménages en impayé suivis par la Fondation pour le logement évoquent des accidents de la vie (perte d'emploi, séparation, santé), et des outils existent pour protéger aussi les petits propriétaires (garantie Visale gratuite, fonds de solidarité, indemnisation par l'État).",
 contexte="Chaque automne, le début de la trêve hivernale relance l'idée de locataires qui profiteraient de l'hiver pour ne plus payer, souvent associée aux squatteurs. La loi du 27 juillet 2023, dite Kasbarian-Bergé, a durci les procédures d'expulsion.",
 explication="On compare ce que dit la loi (service-public.fr) avec les chiffres officiels des expulsions et des impayés (ministère, Fondation pour le logement des défavorisés, commissaires de justice).",
 sources=[E_TH_SP, E_TH_MIN, E_TH_FONDATION, E_TH_BDT, E_TH_APE, E_TH_VISALE],
 faits=[
  fait("Selon service-public.gouv.fr, la trêve hivernale court du 1er novembre 2026 au 31 mars 2027 : elle interdit de procéder à l'expulsion d'un locataire, même avec une décision de justice, mais « ne supprime pas les dettes de loyer accumulées ».", 'e_th_sp', '2026-2027', 'France', "Le loyer reste dû pendant l'hiver ; seule l'exécution de l'expulsion est reportée.", 'etabli', '5 mois'),
  fait("Selon service-public.gouv.fr, les squatteurs d'un domicile, les personnes relogées dans un logement adapté et les conjoints violents ne bénéficient pas de la trêve.", 'e_th_sp', '2026', 'France', "La trêve ne protège pas les occupants illégaux d'un domicile, contrairement à une idée répandue.", 'etabli'),
  fait("Selon le ministère chargé du Logement, 24 556 expulsions locatives ont été réalisées avec le concours de la force publique en 2024 ; selon la Fondation pour le logement des défavorisés, il y en avait eu 19 023 en 2023, déjà un record, et 16 219 en 2022.", 'e_th_min', '2022-2024', 'France', "Les expulsions augmentent fortement : un locataire qui ne paie pas finit très souvent par être expulsé.", 'etabli', '24 556'),
  fait("Selon les commissaires de justice cités par la Banque des Territoires, 30 500 ménages ont dû quitter leur logement après une décision de justice en 2025 (+27 %) ; le délai minimal entre le premier impayé et l'expulsion est de 8 mois, souvent proche de 2 ans à cause des délais d'audience.", 'e_th_bdt', '2025', 'France', "La lenteur vient surtout de l'engorgement des tribunaux, pas de la trêve.", 'estimation', '30 500'),
  fait("Selon la Fondation pour le logement des défavorisés, la loi du 27 juillet 2023 accélère la procédure, restreint les délais accordés aux locataires et prévoit une amende de 7 500 euros pour ceux qui ne partent pas d'eux-mêmes.", 'e_th_fondation', 'depuis 2023', 'France', "Le droit actuel est plus dur pour les locataires, pas plus laxiste.", 'etabli', '7 500 €'),
  fait("Selon le ministère, environ 1,5 million de ménages connaissent chaque année un retard ou un impayé de loyer, pour moitié dans le parc privé et pour moitié dans le parc social ; selon la Fondation pour le logement, les ménages qui appellent sa plateforme sont à 72 % des personnes seules, avec ou sans enfants, et citent la perte d'emploi, la séparation, la santé ou une charge imprévue.", 'e_th_min', '2024-2025', 'France', "L'impayé est d'abord un accident de la vie qui frappe des ménages fragiles.", 'estimation', '1,5 million'),
  fait("Fait défavorable : un propriétaire qui subit un impayé peut attendre plusieurs mois, voire environ deux ans, avant de récupérer son logement, ce qui peut mettre en difficulté un petit bailleur ; des outils existent toutefois : garantie Visale gratuite d'Action Logement, fonds de solidarité pour le logement (330 M€ selon le ministère) et indemnisation par l'État quand il refuse la force publique.", 'e_th_bdt', '2025-2026', 'France', "Il faut protéger à la fois le locataire en difficulté et le petit propriétaire, par la solidarité plutôt que par la rue.", 'interpretation'),
 ],
 court="Non. La trêve hivernale, du 1er novembre au 31 mars, empêche seulement d'exécuter une expulsion en plein hiver : le loyer reste dû, la dette s'accumule et la procédure continue. Et les expulsions avec la force publique battent des records : 24 556 en 2024 selon le ministère.",
 moyen="La trêve hivernale ne suspend pas le loyer. Selon service-public.gouv.fr, elle interdit seulement de mettre un locataire à la rue entre le 1er novembre et le 31 mars, même s'il y a un jugement, et elle « ne supprime pas les dettes de loyer accumulées ». La procédure continue pendant l'hiver, et l'expulsion peut avoir lieu dès le 1er avril. Les squatteurs d'un domicile n'en bénéficient pas.\n\nLoin d'un laxisme, les expulsions avec la force publique explosent : 16 219 en 2022, 19 023 en 2023, 24 556 en 2024, et la loi de juillet 2023 a encore accéléré les procédures. Les ménages en impayé suivis par la Fondation pour le logement évoquent des accidents de la vie : perte d'emploi, séparation, santé. Les difficultés des petits propriétaires sont réelles, mais la réponse passe par la garantie Visale, gratuite, et par les fonds de solidarité, pas par la rue.",
 detaille="La trêve hivernale existe pour une raison simple : éviter de mettre des familles à la rue en plein hiver. Selon service-public.gouv.fr, elle court cette année du 1er novembre 2026 au 31 mars 2027. Pendant cette période, un propriétaire ne peut pas faire exécuter une expulsion, même s'il a obtenu un jugement, et les fournisseurs ne peuvent pas couper le gaz ou l'électricité. Mais la trêve « ne supprime pas les dettes de loyer accumulées » : le loyer reste dû chaque mois, la dette grossit, et la procédure judiciaire continue. Les squatteurs d'un domicile ne sont pas protégés.\n\nLes chiffres contredisent l'idée d'une impunité. Selon le ministère du Logement, 24 556 expulsions ont été réalisées avec le concours de la force publique en 2024 ; selon la Fondation pour le logement des défavorisés, il y en avait 19 023 en 2023, déjà un record historique, et 16 219 en 2022. Selon les commissaires de justice, 30 500 ménages ont dû quitter leur logement après une décision de justice en 2025, un nouveau record. La loi du 27 juillet 2023, dite Kasbarian-Bergé, a accéléré les procédures et réduit les délais accordés aux locataires.\n\nQui sont les locataires en impayé ? Selon le ministère, environ 1,5 million de ménages connaissent chaque année un retard ou un impayé, autant dans le parc social que dans le privé. Les ménages qui appellent la plateforme de prévention de la Fondation pour le logement sont surtout des personnes seules, souvent avec enfants, frappées par une perte d'emploi, une séparation, un problème de santé ou une hausse des charges. Ce ne sont pas des profiteurs, mais des gens qui basculent.\n\nIl faut aussi entendre les petits propriétaires : un impayé peut durer longtemps, car il s'écoule au minimum huit mois, et souvent près de deux ans, entre le premier impayé et l'expulsion, surtout à cause de l'engorgement des tribunaux. Des protections existent : la garantie Visale d'Action Logement, gratuite, couvre les loyers impayés ; les fonds de solidarité pour le logement aident les locataires à rembourser ; et l'État indemnise le propriétaire quand il refuse le concours de la force publique.\n\nLa réponse de gauche, c'est de prévenir l'impayé en amont (aides au logement, encadrement des loyers, accompagnement social), de généraliser une garantie publique contre les impayés et de reloger plutôt que d'expulser. Opposer locataires pauvres et petits propriétaires arrange surtout ceux qui profitent de la crise du logement.",
 empathie="Un petit propriétaire qui compte sur son loyer pour vivre peut être mis en grande difficulté par un impayé, et cette inquiétude est légitime. Mais la trêve hivernale n'efface pas la dette : elle évite seulement qu'une famille se retrouve à la rue en plein hiver.",
 legitimes=["Les procédures d'expulsion sont longues, souvent près de deux ans, surtout à cause de l'engorgement des tribunaux.", "Un impayé prolongé peut fragiliser un petit propriétaire qui compte sur ce revenu.", "Les squats de domicile choquent légitimement ; ils sont exclus de la trêve."],
 contre=[
  ("Pendant la trêve, les locataires n'ont plus à payer.", "Faux : selon service-public.gouv.fr, la trêve « ne supprime pas les dettes de loyer accumulées ». Le loyer reste dû et la procédure continue."),
  ("On ne peut plus expulser personne en France.", "Les expulsions avec la force publique battent des records : 24 556 en 2024 selon le ministère, après 19 023 en 2023."),
  ("La trêve protège les squatteurs.", "Non : selon service-public.gouv.fr, les squatteurs d'un domicile sont exclus de la trêve hivernale."),
 ],
 questions=["Savais-tu que la trêve hivernale n'efface pas un seul euro de dette de loyer ?", "Qu'est-ce qui protégerait le mieux un petit propriétaire : mettre une famille à la rue en hiver, ou une garantie publique contre les impayés ?"],
 limites=["Les chiffres de 2025 (30 500 ménages) viennent de la Chambre nationale des commissaires de justice et portent sur les départs après décision de justice, pas uniquement sur les expulsions avec la force publique ; ils ne sont pas directement comparables aux chiffres du ministère.", "Le profil des ménages vient d'une plateforme associative (1 295 appels) et n'est pas représentatif de l'ensemble des impayés.", "Le rapport de la Fondation pour le logement et le communiqué du ministère ont été lus en partie, à travers un outil de lecture qui résume.", "La part des impayés dits « de bonne foi » n'a été trouvée dans aucune source lue.", "La page d'Action Logement sur Visale n'est pas datée ; les conditions d'accès peuvent évoluer."],
 publics={'convaincus': "Je comprends qu'on soit choqué par l'idée de gens qui ne paient pas. Mais la trêve n'efface aucune dette : elle empêche juste de mettre une famille dehors en plein hiver, et l'expulsion arrive au printemps. Les expulsions avec la police ont atteint un record de 24 556 en 2024. Et les squatteurs, eux, ne sont pas protégés par la trêve.",
  'indecis': "Si tu es propriétaire ou si tu en connais, l'inquiétude est compréhensible. Retiens que le loyer reste dû pendant la trêve, que la procédure continue et que la garantie Visale, gratuite, peut couvrir les impayés. Les locataires en difficulté évoquent souvent une perte d'emploi, une séparation ou un problème de santé : la solution passe par la prévention, pas par la rue en hiver."},
 a_actualiser='2027-05-31', raison="Chiffres des expulsions de 2025 et 2026 publiés par le ministère et la Fondation pour le logement des défavorisés.",
))

# 4 ── « Le travail d'intérêt général (TIG), ça ne sert à rien » ──────────────
E_TIG_CDC = ('e_tig_cdc', src("Évaluation de deux peines alternatives à l'incarcération : le travail d'intérêt général et la détention à domicile sous surveillance électronique (rapport public thématique)", 'Cour des comptes (texte publié par Vie publique)', 'mars 2025',
  'https://www.vie-publique.fr/files/rapport/pdf/297567.pdf',
  "« Le nombre de peines de travaux d'intérêt général prononcées a diminué de 21 % de 2014 à 2023 » ; mesures suivies : 38 529 en 2014, 22 126 fin 2023. Délais d'exécution qui « dépassent en moyenne 16 mois ». Coût moyen d'un TIG : 1 862 € en 2022 (2 788 € pour une détention à domicile sous surveillance électronique). « Le taux de récidive dans les cinq ans après une condamnation à un TIG atteint près de 60 % », proche de celui de l'emprisonnement ferme ; les tigistes ont des profils à risque. Après analyse économétrique neutralisant les caractéristiques socio-économiques, le TIG « ne semble pas plus efficace que l'emprisonnement ferme pour prévenir la récidive », avec des résultats légèrement plus favorables pour la fréquence et la gravité des récidives. La Cour relève un « manque criant d'études ». Un tigiste est reçu en moyenne environ 2,2 fois par le SPIP pendant sa mesure ; 33 % sont orientés vers des acteurs de l'insertion.",
  "Rapport de la Cour des comptes (environ 350 000 caractères, lu en partie à travers un outil de lecture qui résume).", 'primaire'))
E_TIG_BDT = ('e_tig_bdt', src("Travail d'intérêt général : des résultats « peu probants » sur la récidive", 'Banque des Territoires (Localtis)', '5 mars 2025',
  'https://www.banquedesterritoires.fr/travail-dinteret-general-des-resultats-peu-probants-sur-la-recidive',
  "Compte rendu du rapport de la Cour des comptes : récidive de près de 60 % après un TIG, « un niveau proche de celui observé pour les condamnés à des peines d'emprisonnement ferme » ; 46 % après une libération aménagée sous bracelet, 38 % pour un aménagement avant toute incarcération ; recours au TIG : 4,4 pour 100 condamnations en 2014, 2,7 en 2023 ; environ 38 000 places de TIG en 2023 ; coût d'un TIG nettement inférieur à celui de la détention ; 80 130 détenus au 1er novembre 2024, soit un taux d'occupation de 128 %. Selon la Cour, le manque de postes n'est pas la cause de l'échec.",
  "Article de la Caisse des dépôts rapportant le rapport de la Cour des comptes.", 'secondaire'))
