FICHES.append(fiche(
 id='tig-travail-interet-general', affirmation="Le travail d'intérêt général (TIG) ne sert à rien : seule la prison est une vraie sanction.", volet='securite', sous_theme='Justice pénale',
 mots_cles=['travail d interet general', 'tig ca sert a rien', 'tig peine bidon', 'peines alternatives a la prison', 'tig recidive', 'tig ou prison', 'tigiste', 'travaux d interet general efficacite', 'la prison c est mieux que le tig', 'cour des comptes tig'],
 verdict='trompeur', fiabilite='debat',
 resume="Trompeur, mais le TIG n'est pas une solution miracle. La Cour des comptes (2025) constate une récidive d'environ 60 % dans les cinq ans après un TIG, proche de celle des condamnés à la prison ferme, et ne trouve pas d'effet supérieur à la prison, sauf des récidives un peu moins fréquentes et moins graves. Autrement dit, le TIG fait au moins aussi bien que la prison, pour un coût moyen d'environ 1 862 € par mesure et sans aggraver la surpopulation carcérale (128 % fin 2024). Son principal problème est un manque de moyens : délais de plus de seize mois et suivi très faible.",
 contexte="Le TIG est souvent présenté comme une peine « laxiste ». La Cour des comptes a publié en mars 2025 une évaluation sévère, que certains utilisent pour réclamer plus de prison ; elle critique pourtant surtout la mise en œuvre de la peine.",
 explication="On s'appuie sur l'évaluation de la Cour des comptes, sur les chiffres de l'Agence du TIG et sur une étude du ministère de la Justice sur la récidive des sortants de prison, en distinguant ce qui est mesuré et ce qui ne l'est pas.",
 sources=[E_TIG_CDC, E_TIG_BDT, E_TIG_ATIGIP, E_TIG_JUSTICEFR, E_TIG_INFOSTAT],
 faits=[
  fait("Selon le ministère de la Justice, le TIG est un travail non rémunéré de 20 à 400 heures pour un délit, au profit d'une collectivité, d'un établissement public ou d'une association ; s'il n'est pas exécuté, la personne peut être poursuivie ou voir appliquer la peine de prison fixée par le juge.", 'e_tig_justicefr', 'en vigueur', 'France', "C'est une vraie sanction, assortie d'une menace de prison en cas de non-respect.", 'etabli', '400 heures'),
  fait("Selon la Cour des comptes (mars 2025), le taux de récidive dans les cinq ans après une condamnation à un TIG atteint près de 60 %, un niveau proche de celui des condamnés à la prison ferme ; après correction des différences de profils, le TIG « ne semble pas plus efficace que l'emprisonnement ferme », avec des récidives légèrement moins fréquentes et moins graves.", 'e_tig_cdc', '2014-2023', 'France', "Le TIG ne fait pas mieux que la prison sur la récidive, mais pas moins bien non plus.", 'etabli', '60 %'),
  fait("Selon la Cour des comptes, un TIG coûtait en moyenne 1 862 € en 2022 ; selon la Banque des Territoires, qui rend compte du rapport, ce coût est nettement inférieur à celui de la détention, alors que les prisons comptaient 80 130 détenus au 1er novembre 2024, soit un taux d'occupation de 128 %.", 'e_tig_cdc', '2022-2024', 'France', "À efficacité comparable, le TIG coûte beaucoup moins cher et évite d'aggraver la surpopulation carcérale.", 'etabli', '1 862 €'),
  fait("Selon la Cour des comptes, les TIG mettent en moyenne plus de seize mois à être exécutés, un tigiste n'est reçu qu'environ 2,2 fois par le service de probation pendant sa mesure et seuls 33 % sont orientés vers des acteurs de l'insertion.", 'e_tig_cdc', '2020-2023', 'France', "La peine est affaiblie par le manque de moyens de suivi, pas par son principe.", 'etabli', '16 mois'),
  fait("Selon l'Agence du TIG (chiffres d'octobre 2025), il existe 44 000 places de TIG dans plus de 16 000 organismes d'accueil et plus de 23 000 mesures sont prises en charge ; mais selon la Cour des comptes, le nombre de TIG prononcés a baissé de 21 % de 2014 à 2023.", 'e_tig_atigip', '2014-2025', 'France', "Les places existent ; ce sont les prononcés qui reculent, faute de confiance des magistrats dans le suivi.", 'etabli', '44 000'),
  fait("Selon le ministère de la Justice (Infostat, 2021), 31 % des sortants de prison de 2016 ont été recondamnés pour une infraction commise dans l'année ; 33 % après une sortie sans aménagement contre 23 % après une libération conditionnelle, sans que l'étude permette de conclure à un lien de causalité.", 'e_tig_infostat', '2016-2019', 'France', "La prison ne protège pas de la récidive : les sorties accompagnées semblent associées à moins de récidive.", 'estimation', '31 %'),
  fait("Fait défavorable : la Cour des comptes juge les résultats du TIG « insuffisants » et parle d'un « manque criant d'études » sur la récidive après cette peine ; il n'est donc pas démontré que le TIG réduise davantage la récidive que la prison.", 'e_tig_cdc', '2025', 'France', "Défendre le TIG suppose d'admettre ses faiblesses actuelles et d'exiger les moyens de le rendre plus efficace.", 'interpretation'),
 ],
 court="Pas vraiment. Selon la Cour des comptes, la récidive après un TIG (environ 60 % en cinq ans) est proche de celle après la prison ferme : il fait au moins aussi bien, pour un coût d'environ 1 862 € par mesure, sans remplir des prisons occupées à 128 %. Son vrai problème est le manque de suivi : plus de seize mois de délai en moyenne.",
 moyen="Le TIG est une vraie peine : jusqu'à 400 heures de travail non payé au service de la collectivité, avec la prison à la clé si on ne l'exécute pas. La Cour des comptes a évalué cette peine en 2025 : environ 60 % des condamnés récidivent dans les cinq ans, un niveau proche de celui des sortants de prison ferme. Après correction des différences de profils, elle conclut que le TIG ne fait pas mieux que la prison, avec toutefois des récidives un peu moins fréquentes et moins graves.\n\nDire que le TIG « ne sert à rien » est donc trompeur : il fait au moins aussi bien que la prison, coûte beaucoup moins cher (1 862 € en moyenne) et évite d'aggraver la surpopulation (128 % fin 2024). Ce que la Cour pointe, c'est le manque de moyens : seize mois de délai en moyenne et à peine deux rendez-vous de suivi pendant la mesure. La conclusion logique, c'est de renforcer le TIG, pas de construire toujours plus de prisons.",
 detaille="Le travail d'intérêt général est une peine prononcée par un juge : de 20 à 400 heures de travail non rémunéré au profit d'une collectivité, d'un établissement public ou d'une association. Si la personne ne l'exécute pas, elle peut être poursuivie pour ce délit ou voir appliquer la peine de prison prévue. Selon l'Agence du TIG, il existait en octobre 2025 environ 44 000 places dans plus de 16 000 organismes d'accueil.\n\nLa Cour des comptes a publié en mars 2025 une évaluation sans complaisance. Environ 60 % des personnes condamnées à un TIG récidivent dans les cinq ans, un niveau proche de celui des condamnés à la prison ferme. Les tigistes ont souvent des profils à risque (jeunes, peu insérés, passé pénal), et une analyse statistique qui neutralise ces différences conclut que le TIG « ne semble pas plus efficace que l'emprisonnement ferme », avec des récidives un peu moins fréquentes et moins graves. La Cour souligne un « manque criant d'études » sur le sujet.\n\nCe constat ne justifie pas de dire que le TIG ne sert à rien. À efficacité comparable, il coûte environ 1 862 € par mesure, beaucoup moins que la détention, et il évite d'entasser davantage de personnes dans des prisons qui comptaient 80 130 détenus pour un taux d'occupation de 128 % fin 2024. La prison, elle, ne garantit pas la sécurité : selon le ministère de la Justice, 31 % des sortants de prison de 2016 ont été recondamnés pour des faits commis dans l'année, davantage après une sortie sèche qu'après une libération conditionnelle.\n\nLe vrai problème, selon la Cour, c'est la mise en œuvre : plus de seize mois entre la condamnation et l'exécution, environ 2,2 rendez-vous de suivi par mesure, seulement un tiers des tigistes orientés vers l'insertion. Une sanction qui arrive si tard perd son sens. Les magistrats le savent : le nombre de TIG prononcés a baissé de 21 % entre 2014 et 2023, alors que les places ont augmenté.\n\nUne politique pénale de gauche ne choisit pas entre fermeté et réinsertion : elle veut des peines rapides, utiles à la société et capables de faire sortir de la délinquance. Cela passe par plus de conseillers de probation, de travailleurs sociaux et d'accompagnement vers l'emploi, plutôt que par la construction de nouvelles places de prison.",
 empathie="On peut avoir le sentiment qu'une peine sans prison n'est pas une vraie punition, surtout quand on a été victime. C'est une attente légitime de justice, qui mérite une réponse sérieuse sur ce qui protège vraiment de la récidive.",
 legitimes=["La Cour des comptes juge les résultats actuels du TIG insuffisants.", "Les délais d'exécution, plus de seize mois en moyenne, affaiblissent le sens de la peine.", "Le suivi des tigistes par les services de probation est très faible."],
 contre=[
  ("Le TIG, c'est une peine pour rire.", "C'est jusqu'à 400 heures de travail non payé, avec la prison à la clé en cas de non-exécution, selon le ministère de la Justice."),
  ("La Cour des comptes a prouvé que le TIG ne marche pas.", "Elle constate que le TIG ne fait pas mieux que la prison ferme sur la récidive, mais pas moins bien, avec des récidives un peu moins graves ; elle demande surtout de meilleurs moyens de suivi."),
  ("La prison, au moins, empêche de récidiver.", "Selon le ministère de la Justice, 31 % des sortants de prison de 2016 ont été recondamnés dans l'année ; et la prison est déjà occupée à 128 %."),
 ],
 questions=["Si le TIG fait aussi bien que la prison sur la récidive, pour beaucoup moins cher, pourquoi s'en priver ?", "Une peine exécutée seize mois après les faits peut-elle avoir un sens pour la personne condamnée ?"],
 limites=["Le rapport de la Cour des comptes (environ 350 000 caractères) a été lu en partie, à travers un outil de lecture qui résume ; le coût d'une journée de détention n'y a pas été relevé.", "La comparaison entre TIG et prison reste fragile : la Cour elle-même souligne le manque d'études et les différences de profils entre condamnés.", "L'étude Infostat porte sur les sortants de prison de 2016, avec une récidive mesurée sur un an et probablement sous-estimée ; elle est descriptive et ne compare pas avec le TIG.", "L'étude d'Annie Kensey et Abdelmalik Benaouda (2011) sur la récidive des sortants de prison n'a pas pu être ouverte et n'est pas citée.", "Les chiffres de l'Agence du TIG viennent d'un document de présentation institutionnel."],
 publics={'convaincus': "Tu veux que les délinquants paient et ne recommencent pas : moi aussi. La Cour des comptes montre que la prison ferme ne fait pas mieux que le TIG sur la récidive, environ 60 % dans les deux cas, alors qu'elle coûte bien plus cher et que les prisons sont pleines à 128 %. Si on veut moins de récidive, il faut des peines rapides et un vrai suivi, pas seulement des barreaux.",
  'indecis': "C'est légitime de douter d'une peine sans prison. Les faits : le TIG est une vraie sanction, jusqu'à 400 heures de travail, et selon la Cour des comptes il fait à peu près aussi bien que la prison sur la récidive, pour beaucoup moins cher. Son défaut, c'est la lenteur et le manque de suivi : c'est là qu'il faut agir."},
 a_actualiser='2027-06-30', raison="Nouvelles données de l'Agence du TIG et suites données aux recommandations de la Cour des comptes.",
))

# 5 ── « La France est l'un des pays les plus dangereux d'Europe » ──────────────
E_DGR_EUROSTAT23 = ('e_dgr_eurostat23', src("3 930 intentional homicides recorded in the EU in 2023", 'Eurostat (actualité)', '23 avril 2025',
  'https://ec.europa.eu/eurostat/en/web/products-eurostat-news/w/ddn-20250423-1',
  "« In 2023, there were 3 930 intentional homicides in the EU recorded by the police », +1,5 % par rapport à 2022 et -15,2 % par rapport à 2013 (4 635). En nombre absolu, France (887), Allemagne (661) et Italie (338) en comptent le plus ; Malte (2), Luxembourg (4) et Chypre (10) le moins. La page ne donne pas de taux par habitant.",
  "Office statistique de l'Union européenne.", 'primaire'))
E_DGR_EUROSTAT_SE = ('e_dgr_eurostat_se', src("Crime statistics (Statistics Explained)", 'Eurostat', 'avril 2026 (données 2024)',
  'https://ec.europa.eu/eurostat/statistics-explained/index.php?title=Crime_statistics',
  "3 953 homicides volontaires dans l'UE en 2024, +1,4 % par rapport à 2023 ; hausse dans 16 des 27 États membres. Mises en garde : « The number of police-recorded crimes varies widely across the EU, even relative to population size » ; les comparaisons sont affectées par des pratiques d'enregistrement policier et des taux de plainte différents, ainsi que par des lois et systèmes judiciaires différents ; les données policières ne mesurent pas toute la délinquance.",
  "Article de référence d'Eurostat (lu à travers un outil de lecture qui résume) ; les taux par pays figurent dans un graphique non lisible par l'outil.", 'primaire'))
